import React, { useState, useCallback } from 'react';
import styled from '@emotion/styled';
import { Layout, NavTree, theme } from '@atlantis/shared';
import type { NavEntry } from '@atlantis/shared';
import LivePulse from './components/LivePulse';
import AIRadar from './components/AIRadar';
import TodayInTech from './components/TodayInTech';
import ExperimentZone from './components/ExperimentZone';

const SECTIONS: NavEntry[] = [
  {
    id: 'dashboard',
    name: 'Dashboard',
    icon: 'layout-grid',
    children: [
      { id: 'live-pulse', name: 'Live Pulse', icon: 'zap' },
      { id: 'ai-radar', name: 'AI Radar', icon: 'bot' },
      { id: 'today-in-tech', name: 'Today in Tech', icon: 'compass' },
      { id: 'experiment-zone', name: 'Experiment Zone', icon: 'lightbulb' },
    ],
  },
];

const Content = styled.div`
  padding: ${theme.spacing.xl};
  display: flex;
  flex-direction: column;
  gap: ${theme.spacing.xl};
  max-width: 1400px;
  width: 100%;
`;

const Section = styled.section`
  scroll-margin-top: ${theme.spacing.lg};
`;

const MidRow = styled.div`
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: ${theme.spacing.xl};

  @media (max-width: ${theme.breakpoints.lg}) {
    grid-template-columns: 1fr;
  }
`;

const Panel = styled.div`
  background: ${theme.colors.surface};
  border: 1px solid ${theme.colors.border};
  border-radius: ${theme.borderRadius.lg};
  padding: ${theme.spacing.lg};
`;

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const [activeSection, setActiveSection] = useState<string | null>(null);

  const handleSelect = useCallback((entry: NavEntry) => {
    setActiveSection(entry.id);
    document.getElementById(entry.id)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, []);

  const sidebar = (
    <NavTree entries={SECTIONS} activeId={activeSection} onSelect={handleSelect} />
  );

  return (
    <Layout title="TechScope" sidebar={sidebar} activeId={activeSection} topBarRight={topBarRight}>
      <Content>
        <Section id="live-pulse">
          <Panel>
            <LivePulse />
          </Panel>
        </Section>

        <MidRow>
          <Section id="ai-radar">
            <Panel style={{ height: '100%' }}>
              <AIRadar />
            </Panel>
          </Section>
          <Section id="today-in-tech">
            <Panel style={{ height: '100%' }}>
              <TodayInTech />
            </Panel>
          </Section>
        </MidRow>

        <Section id="experiment-zone">
          <Panel>
            <ExperimentZone />
          </Panel>
        </Section>
      </Content>
    </Layout>
  );
}
